exercise.solution:
mod garden {
    pub fn plant(name: &str) -> String {
        format!("planted {name}")
    }

    pub mod vegetables {
        pub fn count() -> u32 {
            3
        }
    }
}

fn main() {
    let count = garden::vegetables::count();
    println!("{}, {} in the garden", garden::plant("carrot"), count);
}
